        [Test]
        public void TestRangeValueMinSerializationNonFinite()
        {
            foreach (var value in new double[] { System.Double.PositiveInfinity, System.Double.NegativeInfinity, System.Double.NaN })
            {
                var node = LoadTheFirstExpected(
                    "RangeValue");

                var instance = Our.Jsonization.Deserialize.RangeValueFrom(
                    node);

                instance.Min = value;

                Our.Jsonization.SerializationException? exception = null;
                try
                {
                    var _ = Our.Jsonization.Serialize.ToJsonObject(instance);
                }
                catch (Our.Jsonization.SerializationException observedException)
                {
                    exception = observedException;
                }

                Assert.IsNotNull(
                    exception,
                    "Expected the serialization to fail at " +
                        "Min" +
                        ", but it succeeded");

                Assert.AreEqual(
                    "Min",
                    exception!.Path);
            }
        }  // public void TestRangeValueMinSerializationNonFinite

